function COMPOSE(a, b, c, d):
    x <- a*c - b*d        # real part of (a+bi)(c+di)
    y <- a*d + b*c        # imaginary part
    return (x, y)         # x^2 + y^2 = (a^2+b^2)(c^2+d^2)

function CLASSIFY(p):
    if p = 2: return ('ramified', (1,1))
    if p mod 4 = 3: return ('inert', None)
    for a = 0 .. floor(sqrt(p)):
        b2 <- p - a*a
        if b2 is a perfect square b^2: return ('split', (a,b))
    return ('inert', None)

