function ENCRYPT(t, s, a, e_re, e_im, m_re, m_im):
    v <- a*s + (e_re + e_im*i) + (m_re*t + m_im*t*i)
    return (a, v)
function DECRYPT(t, s, (u, v)):
    phase <- v - u*s
    return (ROUND(t, Re phase), ROUND(t, Im phase))
function ROUND(t, x): return 0 if 2*x < t else 1

