function BEST_COORD(coord_adv[0..n-1]):
    delta <- sum(coord_adv)
    i <- argmax_k coord_adv[k]
    assert coord_adv[i] >= delta / n
    return (i, coord_adv[i])
function REGEV_BOUND(n, q, alpha):
    assert alpha*q >= 2*sqrt(n)
    return (n/alpha, q*sqrt(n)/2)   # n/alpha <= q*sqrt(n)/2
